/*
cot from trigonometry
        L_i,j = { cot(α_ij) + cot(β_ij) if j ∈ N(i)
        L_i,i = -sum_(k for k != i) L_i,k
        where
        L: ℝ^(n×n)
        α: ℝ^(n×n)
        β: ℝ^(n×n)
        N: ℤ -> {ℤ}

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::SparseMatrix<double> L;

    heartlib(
        const Eigen::MatrixXd & α,
        const Eigen::MatrixXd & β,
        const std::function<std::vector<int >(int)> & N)
    {
        const long n = α.cols();
        assert( α.rows() == n );
        assert( β.rows() == n );
        assert( β.cols() == n );
        // L_i,j = { cot(α_ij) + cot(β_ij) if j ∈ N(i)
        L.resize(n, n);
        std::vector<Eigen::Triplet<DT> > tripletList_L;
        for( int i=1; i<=n; i++){
            for( int j=1; j<=n; j++){
                const std::vector<int >& set = N(i);
                if(std::binary_search(set.begin(), set.end(), int(j))){
                    tripletList_L.push_back(Eigen::Triplet<DT>(i-1, j-1, 1/tan(α(i-1, j-1)) + 1/tan(β(i-1, j-1))));
                }
            }
        }
        L.setFromTriplets(tripletList_L.begin(), tripletList_L.end());
        // L_i,i = -sum_(k for k != i) L_i,k
        for( int i=1; i<=n; i++){
            DT sum_0 = 0;
            for(int k=1; k<=L.cols(); k++){
                if(k != i){
                    sum_0 += this->L.coeff(i-1, k-1);
                }
            }
            tripletList_L.push_back(Eigen::Triplet<DT>(i-1, i-1, -sum_0));
        }
        L.setFromTriplets(tripletList_L.begin(), tripletList_L.end());
    }
};

