function output = heartlib(alpha, beta, N)
% output = heartlib(α, β, N)
%
%    cot from trigonometry
%            L_i,j = { cot(α_ij) + cot(β_ij) if j ∈ N(i)
%            L_i,i = -sum_(k for k != i) L_i,k
%            where
%            L: ℝ^(n×n)
%            α: ℝ^(n×n)
%            β: ℝ^(n×n)
%            N: ℤ -> {ℤ}
%            
    n = size(alpha, 2);
    assert( isequal(size(alpha), [n, n]) );
    assert( isequal(size(beta), [n, n]) );

    % L_i,j = { cot(α_ij) + cot(β_ij) if j ∈ N(i)

    Lij_0 = zeros(2,0);
    Lvals_0 = zeros(1,0);
    for i = 1:n
        for j = 1:n
            if ismember([j],N(i),'rows')
                Lij_0(1:2,end+1) = [i;j];
                Lvals_0(end+1) = 1./tan(alpha(i, j)) + 1./tan(beta(i, j));
            end
        end
    end
    sparse_0 = sparse(Lij_0(1,:),Lij_0(2,:),Lvals_0,n,n);
    L = sparse_0;
    for i = 1:n
        sum_0 = 0;
        for k = 1:size(L,2)
            if k ~= i
              sum_0 = sum_0 + L(i, k);
            end
        end
        Lij_0(1:2,end+1) = [i;i];
        Lvals_0(end+1) = -sum_0;
    end
    L = sparse(Lij_0(1,:),Lij_0(2,:),Lvals_0,n,n);
    output.L = L;
end

